import{describe,it,expect}from"vitest";import{GENERAL_ELECTIONS_DATA,filterElectionsData}from"../../frontend/general-elections-timeline/script.js";describe("Interactive General Elections Timeline",()=>{it("should cover all 18 Lok Sabha elections from 1951 to 2024",()=>{expect(Array.isArray(GENERAL_ELECTIONS_DATA)).toBe(!0),expect(GENERAL_ELECTIONS_DATA.length).toBe(18),GENERAL_ELECTIONS_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("year"),expect(e).toHaveProperty("yearDisplay"),expect(e).toHaveProperty("lokSabha"),expect(e).toHaveProperty("decade"),expect(e).toHaveProperty("winningParty"),expect(e).toHaveProperty("pm"),expect(e).toHaveProperty("turnout"),expect(typeof e.turnout).toBe("number"),expect(e).toHaveProperty("totalSeats"),expect(e).toHaveProperty("seatsWon"),expect(e).toHaveProperty("majorIssues"),expect(e).toHaveProperty("coalitionDetails"),expect(e).toHaveProperty("keyHighlights")})}),it("should filter elections by search term",()=>{const e=filterElectionsData(GENERAL_ELECTIONS_DATA,"Nehru");expect(e.length).toBeGreaterThanOrEqual(3);const t=filterElectionsData(GENERAL_ELECTIONS_DATA,"Emergency");expect(t.length).toBeGreaterThan(0),expect(t[0].year).toBe(1977)}),it("should filter elections by decade",()=>{const e=filterElectionsData(GENERAL_ELECTIONS_DATA,"","1990s","all");expect(e.length).toBe(4),e.forEach(e=>expect(e.decade).toBe("1990s"))}),it("should filter elections by winning party category",()=>{const e=filterElectionsData(GENERAL_ELECTIONS_DATA,"","all","BJP / NDA");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.partyCategory).toBe("BJP / NDA"))})});